import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.awt.image.BufferedImage;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.Transferable;
import java.awt.datatransfer.UnsupportedFlavorException;
import javax.imageio.ImageIO;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.List;
import java.util.regex.*;

/** A compact UML sketch editor implementing a runnable subset of the supplied brief. */
public class Main {
  static final Map<String,List<String>> TOOLS=new LinkedHashMap<>();
  static {TOOLS.put("Class",List.of("Select","Class","Interface","Package","Package Description","Note","Dependency","Inheritance","Realization","Association","Aggregation","Composition","Note Connector","To Clipboard"));TOOLS.put("Sequence",List.of("Select","Implicit Parameter","Note","Call","Return","Note Connector","To Clipboard"));TOOLS.put("State",List.of("Select","State","Initial State","Final State","Note","Transition","Note Connector","To Clipboard"));TOOLS.put("Object",List.of("Select","Object","Field","Note","Reference","Collaboration","Note Connector","To Clipboard"));TOOLS.put("Use Case",List.of("Select","Actor","Use Case","Note","Association","Include","Extend","Generalization","Note Connector","To Clipboard"));}
  static class Item {int id,x,y,w=150,h=70;String type,name;Item(int i,String t,int a,int b){id=i;type=t;name=t;x=a;y=b;if(t.equals("Note")){w=110;h=55;}}}
  static class Edge {int a,b;String type,label="";Edge(int x,int y,String t){a=x;b=y;type=t;}}
  static class Model {String diagram="Class";ArrayList<Item>nodes=new ArrayList<>();ArrayList<Edge>edges=new ArrayList<>();int next=1;}
  static class App extends JFrame {
    Model model=new Model();String tool="Select";Item selected;Set<Item>selection=new LinkedHashSet<>();List<Item>clipboardNodes=new ArrayList<>();List<Edge>clipboardEdges=new ArrayList<>();Point offset;String dragBefore;Item edgeStart;Path path;double zoom=1.0;Deque<String>undo=new ArrayDeque<>(),redo=new ArrayDeque<>();Canvas canvas=new Canvas();JComboBox<String> diagram=new JComboBox<>(TOOLS.keySet().toArray(String[]::new));JPanel tools=new JPanel();
    App(){super("JetUML Sketch — EXA871");setDefaultCloseOperation(EXIT_ON_CLOSE);setLayout(new BorderLayout());add(tools,BorderLayout.WEST);add(canvas,BorderLayout.CENTER);setJMenuBar(menu());diagram.addActionListener(e->{model.diagram=(String)diagram.getSelectedItem();rebuildTools();});rebuildTools();setSize(1120,760);setLocationRelativeTo(null);}
    JMenuBar menu(){JMenuBar b=new JMenuBar();JMenu f=new JMenu("File");f.add(item("New",e->newDiagram()));f.add(item("Open",e->open()));f.add(item("Save",e->save(false)));f.add(item("Save As",e->save(true)));f.add(item("Duplicate",e->{checkpoint();model=copy(model);canvas.repaint();}));f.add(item("Copy Diagram to Clipboard",e->copyDiagramToClipboard()));f.add(item("Export Image (PNG/JPEG)",e->exportImage()));f.add(item("Exit",e->dispose()));b.add(f);JMenu edit=new JMenu("Edit");edit.add(item("Undo",e->undo()));edit.add(item("Redo",e->redo()));edit.add(item("Select All",e->{selection.clear();selection.addAll(model.nodes);selected=null;canvas.repaint();}));JMenuItem cut=item("Cut",e->{copySelected();delete();});cut.setAccelerator(KeyStroke.getKeyStroke(KeyEvent.VK_X,InputEvent.CTRL_DOWN_MASK));edit.add(cut);JMenuItem cp=item("Copy",e->copySelected());cp.setAccelerator(KeyStroke.getKeyStroke(KeyEvent.VK_C,InputEvent.CTRL_DOWN_MASK));edit.add(cp);JMenuItem paste=item("Paste",e->pasteSelected());paste.setAccelerator(KeyStroke.getKeyStroke(KeyEvent.VK_V,InputEvent.CTRL_DOWN_MASK));edit.add(paste);edit.add(item("Delete",e->delete()));edit.add(item("Properties",e->properties()));b.add(edit);JMenu view=new JMenu("View");view.add(item("Show Grid",e->{canvas.grid=!canvas.grid;canvas.repaint();}));view.add(item("Dark Mode",e->{canvas.dark=!canvas.dark;canvas.repaint();}));view.add(item("Zoom In",e->{zoom=Math.min(2.5,zoom*1.2);canvas.repaint();}));view.add(item("Zoom Out",e->{zoom=Math.max(.35,zoom/1.2);canvas.repaint();}));view.add(item("Reset Zoom",e->{zoom=1.0;canvas.repaint();}));b.add(view);return b;}
    JMenuItem item(String s,ActionListener a){JMenuItem i=new JMenuItem(s);i.addActionListener(a);return i;}
    void rebuildTools(){tools.removeAll();tools.setLayout(new BoxLayout(tools,BoxLayout.Y_AXIS));tools.add(new JLabel("Diagram type"));tools.add(diagram);int i=1;for(String t:TOOLS.get(model.diagram)){final String name=t;String key=i<10?i+"  ":(i==10?"0  ":Character.toString((char)('A'+i-11))+"  ");JButton b=new JButton(key+t);b.setHorizontalAlignment(SwingConstants.LEFT);b.setToolTipText("Selecionar ferramenta "+key);b.addActionListener(e->activateTool(name));tools.add(b);i++;}tools.revalidate();tools.repaint();}
    void activateTool(String name){if(name.equals("To Clipboard")){copyDiagramToClipboard();tool="Select";}else tool=name;}
    void chooseTool(int index){List<String> ts=TOOLS.get(model.diagram);if(index>=0&&index<ts.size())activateTool(ts.get(index));}
    void checkpoint(){undo.push(encode(model));redo.clear();}void undo(){if(!undo.isEmpty()){redo.push(encode(model));model=decode(undo.pop());diagram.setSelectedItem(model.diagram);rebuildTools();canvas.repaint();}}void redo(){if(!redo.isEmpty()){undo.push(encode(model));model=decode(redo.pop());diagram.setSelectedItem(model.diagram);rebuildTools();canvas.repaint();}}
    Model copy(Model m){return decode(encode(m));}
    void newDiagram(){String k=(String)JOptionPane.showInputDialog(this,"Diagram type","New diagram",JOptionPane.PLAIN_MESSAGE,null,TOOLS.keySet().toArray(),"Class");if(k!=null){checkpoint();model=new Model();model.diagram=k;diagram.setSelectedItem(k);rebuildTools();canvas.repaint();}}
    void addNode(int x,int y,String t){checkpoint();Item n=new Item(model.next++,t,Math.max(0,Math.round(x/20f)*20),Math.max(0,Math.round(y/20f)*20));model.nodes.add(n);canvas.repaint();}
    Item hit(int x,int y){for(int i=model.nodes.size()-1;i>=0;i--){Item n=model.nodes.get(i);if(x>=n.x&&x<=n.x+n.w&&y>=n.y&&y<=n.y+n.h)return n;}return null;}
    List<Item> selectedNodes(){return selection.isEmpty()?(selected==null?List.of():List.of(selected)):new ArrayList<>(selection);}
    void copySelected(){List<Item> chosen=selectedNodes();Set<Integer> ids=new HashSet<>();clipboardNodes=new ArrayList<>();for(Item n:chosen){ids.add(n.id);Item c=new Item(n.id,n.type,n.x,n.y);c.name=n.name;c.w=n.w;c.h=n.h;clipboardNodes.add(c);}clipboardEdges=new ArrayList<>();for(Edge e:model.edges)if(ids.contains(e.a)&&ids.contains(e.b))clipboardEdges.add(new Edge(e.a,e.b,e.type));}
    void pasteSelected(){if(clipboardNodes.isEmpty())return;checkpoint();Map<Integer,Integer> remap=new HashMap<>();selection.clear();for(Item old:clipboardNodes){Item n=new Item(model.next++,old.type,old.x+20,old.y+20);n.name=old.name;n.w=old.w;n.h=old.h;model.nodes.add(n);remap.put(old.id,n.id);selection.add(n);}for(Edge old:clipboardEdges)model.edges.add(new Edge(remap.get(old.a),remap.get(old.b),old.type));selected=null;canvas.repaint();}
    void properties(){if(selected==null)return;String v=JOptionPane.showInputDialog(this,"Name / text",selected.name);if(v!=null){checkpoint();selected.name=v;canvas.repaint();}}
    void delete(){List<Item>chosen=selectedNodes();if(chosen.isEmpty())return;checkpoint();Set<Integer>ids=new HashSet<>();for(Item n:chosen)ids.add(n.id);model.nodes.removeIf(n->ids.contains(n.id));model.edges.removeIf(e->ids.contains(e.a)||ids.contains(e.b));selection.clear();selected=null;canvas.repaint();}
    void save(boolean as){if(path==null||as){JFileChooser c=new JFileChooser();if(path!=null)c.setSelectedFile(path.toFile());if(c.showSaveDialog(this)==JFileChooser.APPROVE_OPTION){path=c.getSelectedFile().toPath();if(!path.toString().endsWith(".json"))path=Path.of(path+".json");}}if(path!=null)try{Files.writeString(path,encode(model));}catch(Exception ex){error(ex);}}
    void open(){JFileChooser c=new JFileChooser();if(c.showOpenDialog(this)==JFileChooser.APPROVE_OPTION)try{Model loaded=decode(Files.readString(c.getSelectedFile().toPath()));if(!TOOLS.containsKey(loaded.diagram))throw new IllegalArgumentException("Unknown diagram type");Set<Integer> ids=new HashSet<>();for(Item n:loaded.nodes)if(!ids.add(n.id))throw new IllegalArgumentException("Duplicate node id");for(Edge e:loaded.edges)if(!ids.contains(e.a)||!ids.contains(e.b))throw new IllegalArgumentException("Edge endpoint does not exist");checkpoint();model=loaded;path=c.getSelectedFile().toPath();diagram.setSelectedItem(model.diagram);rebuildTools();canvas.repaint();}catch(Exception ex){error(ex);}}
    void exportImage(){JFileChooser c=new JFileChooser();c.setSelectedFile(new File("diagram.png"));if(c.showSaveDialog(this)==JFileChooser.APPROVE_OPTION)try{File target=c.getSelectedFile();String lower=target.getName().toLowerCase(Locale.ROOT);String format=lower.endsWith(".jpg")||lower.endsWith(".jpeg")?"jpg":"png";int type=format.equals("jpg")?BufferedImage.TYPE_INT_RGB:BufferedImage.TYPE_INT_ARGB;BufferedImage im=new BufferedImage(canvas.getWidth(),canvas.getHeight(),type);Graphics2D g=im.createGraphics();canvas.paint(g);g.dispose();if(!ImageIO.write(im,format,target))throw new IOException("Image format unavailable");}catch(Exception ex){error(ex);}}
    void copyDiagramToClipboard(){try{BufferedImage image=new BufferedImage(Math.max(1,canvas.getWidth()),Math.max(1,canvas.getHeight()),BufferedImage.TYPE_INT_ARGB);Graphics2D g=image.createGraphics();canvas.paint(g);g.dispose();Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new ImageSelection(image),null);canvas.setToolTipText("Diagrama copiado para o clipboard do sistema.");}catch(Exception ex){error(ex);}}
    static final class ImageSelection implements Transferable {private final Image image;ImageSelection(Image pImage){image=pImage;}public DataFlavor[] getTransferDataFlavors(){return new DataFlavor[]{DataFlavor.imageFlavor};}public boolean isDataFlavorSupported(DataFlavor flavor){return DataFlavor.imageFlavor.equals(flavor);}public Object getTransferData(DataFlavor flavor)throws UnsupportedFlavorException{if(!isDataFlavorSupported(flavor))throw new UnsupportedFlavorException(flavor);return image;}}
    void error(Exception ex){JOptionPane.showMessageDialog(this,ex.toString(),"Error",JOptionPane.ERROR_MESSAGE);}
    class Canvas extends JPanel {boolean grid=true,dark=false;Canvas(){setPreferredSize(new Dimension(900,700));addMouseListener(new MouseAdapter(){public void mousePressed(MouseEvent e){if(SwingUtilities.isRightMouseButton(e)){JPopupMenu p=new JPopupMenu();for(String t:TOOLS.get(model.diagram)){JMenuItem i=new JMenuItem(t);i.addActionListener(a->activateTool(t));p.add(i);}p.show(Canvas.this,e.getX(),e.getY());return;}Item n=hit((int)(e.getX()/zoom),(int)(e.getY()/zoom));if(isEdge(tool)){if(n!=null){if(edgeStart==null)edgeStart=n;else if(edgeStart!=n){checkpoint();model.edges.add(new Edge(edgeStart.id,n.id,tool));edgeStart=null;repaint();}}return;}if(!tool.equals("Select")){addNode((int)(e.getX()/zoom),(int)(e.getY()/zoom),tool);return;}if((e.getModifiersEx()&InputEvent.CTRL_DOWN_MASK)!=0){if(n!=null){if(!selection.add(n))selection.remove(n);}selected=null;repaint();return;}selected=n;selection.clear();if(n!=null){selection.add(n);dragBefore=encode(model);offset=new Point((int)(e.getX()/zoom)-n.x,(int)(e.getY()/zoom)-n.y);}}public void mouseReleased(MouseEvent e){if(selected!=null){selected.x=Math.max(0,Math.round(selected.x/20f)*20);selected.y=Math.max(0,Math.round(selected.y/20f)*20);if(!dragBefore.equals(encode(model))){undo.push(dragBefore);redo.clear();}selected=null;dragBefore=null;repaint();}}public void mouseClicked(MouseEvent e){if(e.getClickCount()==2){selected=hit((int)(e.getX()/zoom),(int)(e.getY()/zoom));properties();}}});addMouseMotionListener(new MouseMotionAdapter(){public void mouseDragged(MouseEvent e){if(selected!=null&&tool.equals("Select")){selected.x=Math.max(0,(int)(e.getX()/zoom)-offset.x);selected.y=Math.max(0,(int)(e.getY()/zoom)-offset.y);repaint();}}});}
      boolean isEdge(String t){return List.of("Dependency","Inheritance","Realization","Association","Aggregation","Composition","Note Connector","Call","Return","Transition","Reference","Collaboration","Include","Extend","Generalization").contains(t);}
      protected void paintComponent(Graphics gg){super.paintComponent(gg);Graphics2D g=(Graphics2D)gg;g.setColor(dark?new Color(40,43,48):Color.WHITE);g.fillRect(0,0,getWidth(),getHeight());g.scale(zoom,zoom);if(grid){g.setColor(dark?new Color(60,64,70):new Color(232,232,232));for(int x=0;x<getWidth()/zoom;x+=20)g.drawLine(x,0,x,(int)(getHeight()/zoom));for(int y=0;y<getHeight()/zoom;y+=20)g.drawLine(0,y,(int)(getWidth()/zoom),y);}Map<Integer,Item>by=new HashMap<>();for(Item n:model.nodes)by.put(n.id,n);g.setColor(dark?Color.WHITE:Color.BLACK);for(Edge e:model.edges){Item a=by.get(e.a),b=by.get(e.b);if(a!=null&&b!=null){int x1=a.x+a.w/2,y1=a.y+a.h/2,x2=b.x+b.w/2,y2=b.y+b.h/2;g.drawLine(x1,y1,x2,y2);g.fillOval(x2-4,y2-4,8,8);}}for(Item n:model.nodes){g.setColor(n.type.equals("Note")?new Color(255,244,190):Color.WHITE);if(n.type.equals("Initial State"))g.setColor(Color.BLACK);if(n.type.contains("State"))g.fillOval(n.x,n.y,n.w/2,n.h/2);else g.fillRect(n.x,n.y,n.w,n.h);g.setColor(dark?Color.WHITE:Color.BLACK);if(!n.type.equals("Initial State"))g.drawRect(n.x,n.y,n.type.contains("State")?n.w/2:n.w,n.type.contains("State")?n.h/2:n.h);g.drawString(n.name,n.x+8,n.y+25);if(selection.contains(n)){g.setColor(new Color(8,126,139));g.drawRect(n.x-3,n.y-3,n.w+6,n.h+6);}}}
    }
    static String esc(String s){return s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t");}
    static String encode(Model m){StringBuilder b=new StringBuilder("{\"schema\":\"jetuml-sketch-v1\",\"diagram\":\""+esc(m.diagram)+"\",\"nodes\":[");for(int i=0;i<m.nodes.size();i++){Item n=m.nodes.get(i);if(i>0)b.append(',');b.append("{\"id\":"+n.id+",\"type\":\""+esc(n.type)+"\",\"name\":\""+esc(n.name)+"\",\"x\":"+n.x+",\"y\":"+n.y+",\"w\":"+n.w+",\"h\":"+n.h+"}");}b.append("],\"edges\":[");for(int i=0;i<m.edges.size();i++){Edge e=m.edges.get(i);if(i>0)b.append(',');b.append("{\"type\":\""+esc(e.type)+"\",\"a\":"+e.a+",\"b\":"+e.b+",\"label\":\""+esc(e.label)+"\"}");}return b.append("]}").toString();}
    static class JsonReader {final String s;int i;JsonReader(String text){s=text;}void ws(){while(i<s.length()&&Character.isWhitespace(s.charAt(i)))i++;}char take(){ws();if(i>=s.length())throw new IllegalArgumentException("Unexpected end of JSON");return s.charAt(i++);}void expect(char c){if(take()!=c)throw new IllegalArgumentException("Expected '"+c+"'");}Object value(){char c=take();if(c=='{'){Map<String,Object>m=new LinkedHashMap<>();ws();if(i<s.length()&&s.charAt(i)=='}'){i++;return m;}while(true){String k=(String)value();expect(':');m.put(k,value());char end=take();if(end=='}')return m;if(end!=',')throw new IllegalArgumentException("Expected comma");}}if(c=='['){List<Object>a=new ArrayList<>();ws();if(i<s.length()&&s.charAt(i)==']'){i++;return a;}while(true){a.add(value());char end=take();if(end==']')return a;if(end!=',')throw new IllegalArgumentException("Expected comma");}}if(c=='\"'){StringBuilder b=new StringBuilder();while(i<s.length()){char x=s.charAt(i++);if(x=='\"')return b.toString();if(x=='\\'){if(i>=s.length())throw new IllegalArgumentException("Invalid escape");char e=s.charAt(i++);switch(e){case '"','\\','/'->b.append(e);case 'n'->b.append('\n');case 'r'->b.append('\r');case 't'->b.append('\t');case 'b'->b.append('\b');case 'f'->b.append('\f');case 'u'->{if(i+4>s.length())throw new IllegalArgumentException("Invalid unicode escape");b.append((char)Integer.parseInt(s.substring(i,i+4),16));i+=4;}default->throw new IllegalArgumentException("Invalid escape");}}else b.append(x);}throw new IllegalArgumentException("Unterminated string");}int start=i-1;while(i<s.length()&&",]} \r\n\t".indexOf(s.charAt(i))<0)i++;String atom=s.substring(start,i);if(atom.equals("true"))return true;if(atom.equals("false"))return false;if(atom.equals("null"))return null;try{return Integer.valueOf(atom);}catch(NumberFormatException ex){throw new IllegalArgumentException("Unsupported JSON value: "+atom);}}}
    static Model decode(String json){Object parsed=new JsonReader(json).value();if(!(parsed instanceof Map<?,?> data))throw new IllegalArgumentException("Invalid JSON document");Object kind=data.get("diagram");if(!(kind instanceof String)||!TOOLS.containsKey(kind))throw new IllegalArgumentException("Unknown diagram type");Model m=new Model();m.diagram=(String)kind;Object ns=data.get("nodes"),es=data.get("edges");if(!(ns instanceof List<?> nodeList)||!(es instanceof List<?> edgeList))throw new IllegalArgumentException("Nodes and edges arrays are required");Set<Integer> ids=new HashSet<>();for(Object value:nodeList){Map<?,?> n=(Map<?,?>)value;int id=((Number)n.get("id")).intValue();String type=(String)n.get("type"),name=(String)n.get("name");Item item=new Item(id,type,((Number)n.get("x")).intValue(),((Number)n.get("y")).intValue());item.name=name;item.w=((Number)n.get("w")).intValue();item.h=((Number)n.get("h")).intValue();if(!ids.add(id))throw new IllegalArgumentException("Duplicate node id");m.nodes.add(item);m.next=Math.max(m.next,id+1);}for(Object value:edgeList){Map<?,?> e=(Map<?,?>)value;Edge edge=new Edge(((Number)e.get("a")).intValue(),((Number)e.get("b")).intValue(),(String)e.get("type"));Object label=e.get("label");edge.label=label==null?"":(String)label;if(!ids.contains(edge.a)||!ids.contains(edge.b))throw new IllegalArgumentException("Edge endpoint does not exist");m.edges.add(edge);}return m;}
  }
  public static void main(String[]args){if(args.length>0&&args[0].equals("--smoke")){Model m=new Model();m.diagram="Class";Item a=new Item(1,"Class",20,20),b=new Item(2,"Interface",220,20);a.name="Classe com \"aspas\" e barra \\";m.nodes.add(a);m.nodes.add(b);m.edges.add(new Edge(1,2,"Realization"));String json=App.encode(m);Model restored=App.decode(json);if(TOOLS.size()!=5||restored.nodes.size()!=2||restored.edges.size()!=1||!restored.nodes.get(0).name.equals(a.name))throw new IllegalStateException("JSON round-trip failed");restored.nodes.get(0).x+=40;restored=App.decode(App.encode(App.decode(json)));if(restored.nodes.get(0).x!=20)throw new IllegalStateException("Model copy failed");try{App.decode("{bad json");throw new IllegalStateException("Malformed JSON was accepted");}catch(IllegalArgumentException expected){}System.out.println("JetUML Java model OK: five diagram families, escaped JSON round-trip, malformed JSON rejection.");return;}SwingUtilities.invokeLater(()->new App().setVisible(true));}
}


